/* eslint-disable @typescript-eslint/no-explicit-any */
import React, {
  ChangeEvent,
  useRef,
  useCallback,
  useEffect,
  useState,
  useImperativeHandle,
} from 'react';
import {
  useTable,
  useSortBy,
  usePagination,
  useGlobalFilter,
  useRowSelect,
  Row,
} from 'react-table';
import { SortAscending, SortDescending } from '@hexa-ui/icons';
import Styled from './Table.styles';
import { HeaderAllSelectionType, TableProps, OnDeselectAllProps } from './Table.types';
import TableRow from './components/TableRow/TableRow';
import TableLoading from './components/TableLoading/TableLoading';
import EmptyTable from './components/EmptyTable/EmptyTable';
import TableFooter from './components/TableFooter/TableFooter';
import { Checkbox } from '../checkbox';
import { TextButton } from '../text-button';
import { Heading, Paragraph } from '../typography';
import * as SearchField from '../search-field';

const DEFAULT_PAGINATION = {
  pageSize: 10,
  pageSizeOptions: [10, 25, 50],
  showPageSizeSelector: false,
};

const Table = <T,>(
  {
    columns,
    data,
    fixedHeader,
    tableHeight,
    expandable,
    onSort,
    loading,
    tableWidth,
    initialSortBy = [],
    loadingMessage = 'Loading items...',
    emptyMessage = "There's no information to show",
    pagination = DEFAULT_PAGINATION,
    cellHeight = 'loose',
    selectable = undefined,
    onSearchChange,
    initialValueSearch,
    search,
    searchPlaceholder = 'Search',
    toolbarExtra,
    onRow,
  }: TableProps<T> & { ref?: React.ForwardedRef<HTMLButtonElement> },
  fowardedRef: React.ForwardedRef<HTMLButtonElement>
): JSX.Element => {
  const firstRender = useRef(true);
  const isControlledPagination = pagination !== false && pagination.total && pagination.total >= 0;
  const controlledPagination = isControlledPagination
    ? {
        manualPagination: true,
        pageCount: pagination.total,
      }
    : {
        autoResetPage: false,
      };

  const HEADER_CHECKBOX_IDENTIFIER = 'checkbox-selection';
  const tableInstance = useTable(
    {
      columns,
      initialState: {
        sortBy: initialSortBy,
        selectedRowIds: selectable?.initialSelectedState || {},
        pageSize: pagination !== false ? pagination.pageSize : 10,
      },
      data,
      manualSortBy: onSort && typeof onSort === 'function',
      ...controlledPagination,
    } as any,
    useGlobalFilter,
    useSortBy,
    usePagination,
    useRowSelect,
    (hooks) => {
      if (selectable && selectable?.useCheckbox) {
        // eslint-disable-next-line no-shadow
        hooks.visibleColumns.push((columns) => [
          {
            id: HEADER_CHECKBOX_IDENTIFIER,
            Header: ({ getToggleAllPageRowsSelectedProps }) => {
              const { checked, indeterminate } = getToggleAllPageRowsSelectedProps();
              return (
                <Checkbox
                  css={{ textAlign: 'center' }}
                  size="small"
                  data-testid="checkbox-header"
                  onClick={() => onHeaderRowSelect(checked)}
                  checked={indeterminate ? 'indeterminate' : checked}
                />
              );
            },
            Cell: ({ row }) => (
              <Checkbox
                onClick={(event) => {
                  onTableRowSelect(row);
                  event.stopPropagation();
                }}
                checked={row.isSelected}
              />
            ),
          },
          ...columns,
        ]);
      }
    }
  );
  const [tableState, setTableState] = useState<'EMPTY' | 'LOADING' | 'WITH_DATA'>('EMPTY');

  useEffect(() => {
    if (loading) {
      setTableState('LOADING');
      return;
    }

    if (!data || data.length === 0) {
      setTableState('EMPTY');
      return;
    }

    setTableState('WITH_DATA');
  }, [data, loading]);

  const {
    getTableProps,
    getTableBodyProps,
    headerGroups,
    rows,
    prepareRow,
    page,
    state: { sortBy },
    gotoPage,
    setPageSize,
    state: { pageIndex, pageSize },
    setGlobalFilter,
    allColumns,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } = tableInstance as any;

  useEffect(() => {
    if (!firstRender.current) {
      if (onSort && typeof onSort === 'function') {
        if (sortBy[0]) {
          const { id, desc } = sortBy[0];
          onSort(id, desc ? 'DESC' : 'ASC');
        } else {
          onSort(undefined, undefined);
        }
      }
    } else {
      firstRender.current = false;
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sortBy]);

  useEffect(() => {
    if (initialValueSearch) {
      setGlobalFilter(initialValueSearch);
    }
  }, [initialValueSearch, setGlobalFilter]);

  const onPaginationChange = (currentPage: number, currentPageSize: number) => {
    gotoPage(currentPage - 1);
    setPageSize(currentPageSize);
    if (pagination && pagination.onChange) {
      pagination.onChange(currentPage, currentPageSize);
    }
  };

  const onSearch = (e: ChangeEvent<HTMLInputElement>) => {
    gotoPage(0);
    if (onSearchChange && typeof onSearchChange === 'function') onSearchChange(e.target.value);
    else setGlobalFilter(e.target.value);
  };

  const clearSearch = () => {
    if (onSearchChange && typeof onSearchChange === 'function') onSearchChange('');
    else setGlobalFilter('');
  };

  const headerSelectionTypeIsAllPageRows = (): boolean =>
    !selectable?.headerSelectionType ||
    selectable.headerSelectionType.valueOf() === HeaderAllSelectionType.ALL_PAGE_ROWS.valueOf();

  const getRowsEventData = (checked: boolean | undefined) => ({
    rowIds: Object.keys(tableInstance.state.selectedRowIds),
    data: tableInstance.selectedFlatRows as unknown as T[],
    checked: !checked,
  });

  const onHeaderRowSelect = async (checked: boolean | undefined) => {
    if (headerSelectionTypeIsAllPageRows()) {
      // eslint-disable-next-line dot-notation
      await tableInstance['toggleAllPageRowsSelected'](!checked);
      selectable?.onAllPageRowsSelect?.(getRowsEventData(checked));
    } else {
      await tableInstance.toggleAllRowsSelected(!checked);
      selectable?.onAllRowsSelect?.(getRowsEventData(checked));
    }
  };

  const onDeselectAll = useCallback(() => {
    tableInstance.toggleAllRowsSelected(false);
    selectable?.onDeselectAll?.();
  }, [selectable, tableInstance]);

  useImperativeHandle(fowardedRef, () => ({ onDeselectAll } as OnDeselectAllProps));

  useEffect(() => {
    const handleEsc = (event: KeyboardEvent) => {
      if (selectable) {
        if (event.key === 'Escape') {
          onDeselectAll();
        }
      }
    };

    window.addEventListener('keydown', handleEsc);
    return () => {
      window.removeEventListener('keydown', handleEsc);
    };
  }, [onDeselectAll, selectable]);

  const onTableRowSelect = (row: Row<any>) => {
    selectable?.onRowSelect?.({
      rowId: row.id,
      data: row.values as T[],
      checked: !row.isSelected,
    });
    row.toggleRowSelected(!row.isSelected);
  };

  const hasItemSelected = useCallback(
    (): boolean => tableInstance.selectedFlatRows.length > 0,
    [tableInstance.selectedFlatRows.length]
  );

  useEffect(() => {
    if (!hasItemSelected() && selectable) setGlobalFilter(null);
  }, [hasItemSelected, setGlobalFilter, selectable]);

  const getSelectedItemsCounter = (): number => {
    if (selectable?.counter !== undefined) return Number(selectable.counter);
    if (hasItemSelected()) return tableInstance.selectedFlatRows.length;
    return 0;
  };

  const getSelectedItemsToolbarText = (): string => {
    const selectedItems = getSelectedItemsCounter();
    if (selectedItems === 1) {
      return `${selectedItems} ${selectable?.displayTextOneRowSelected ?? 'selected'}`;
    }
    return `${selectedItems} ${selectable?.displayTextMoreThanOneRowSelected ?? 'selecteds'}`;
  };

  const getDeselectAllText = (): string => selectable?.displayTextDeselectAll ?? 'Deselect All';

  const getColumnsQuantity = () => {
    let columnsQuantity = tableInstance.headers.length;
    if (expandable) columnsQuantity += 1;
    return columnsQuantity;
  };

  const isCheckboxHeaderColumn = (columnIdentifier: any): boolean =>
    columnIdentifier && HEADER_CHECKBOX_IDENTIFIER === columnIdentifier;

  return (
    <Styled.Container css={{ width: tableWidth || '100%' }}>
      {(search || selectable || toolbarExtra) && (
        <Styled.Toolbar data-testid="table-toolbar">
          {selectable && !!getSelectedItemsCounter() && (
            <Styled.SelectableActionToolbarContainer>
              <Paragraph>{getSelectedItemsToolbarText()}</Paragraph>
              <Paragraph css={{ padding: '0 $1' }}>/</Paragraph>
              <TextButton onClick={() => onDeselectAll()}>{getDeselectAllText()}</TextButton>
            </Styled.SelectableActionToolbarContainer>
          )}
          {search && !hasItemSelected() && (
            <SearchField.Root
              width="300px"
              placeholder={searchPlaceholder}
              onClear={clearSearch}
              onChange={onSearch}
              defaultValue={initialValueSearch}
            />
          )}
          {toolbarExtra && (
            <Styled.ToolbarContext>
              {toolbarExtra({ allColumns }, { selectedRows: [] })}
            </Styled.ToolbarContext>
          )}
        </Styled.Toolbar>
      )}
      <Styled.TableContainer css={{ height: tableHeight || 'auto' }}>
        <Styled.Table {...getTableProps()}>
          <Styled.Thead fixedHeader={fixedHeader}>
            {headerGroups.map((headerGroup: any) => (
              // eslint-disable-next-line react/jsx-key
              <tr {...headerGroup.getHeaderGroupProps()}>
                {expandable?.rowHasExpandFeature && <Styled.Th />}
                {headerGroup.headers.map((column: any) => (
                  // eslint-disable-next-line react/jsx-key
                  <Styled.Th
                    {...column.getHeaderProps(column.getSortByToggleProps())}
                    showSort={column.canSort && !column.isSorted}
                    canSort={column.canSort}
                    css={{
                      minWidth: column?.style?.minWidth,
                      width: column?.style?.width,
                    }}
                  >
                    <Styled.ThContainer
                      alignment={
                        isCheckboxHeaderColumn(column.id) ? 'center' : column.alignment || 'left'
                      }
                    >
                      <Heading selectable="false" size="H5" css={{ margin: 0 }}>
                        {column.render('Header')}
                      </Heading>
                      <Styled.SortIconContainer show={column.canSort}>
                        {column.canSort && !column.isSorted && (
                          <Styled.Sort size="medium" className="default-sort-icon" />
                        )}
                        {column.isSorted && !column.isSortedDesc && <SortAscending size="medium" />}
                        {column.isSorted && column.isSortedDesc && <SortDescending size="medium" />}
                      </Styled.SortIconContainer>
                    </Styled.ThContainer>
                  </Styled.Th>
                ))}
              </tr>
            ))}
          </Styled.Thead>
          <Styled.Tbody {...getTableBodyProps()}>
            {tableState === 'LOADING' && (
              <TableLoading span={getColumnsQuantity()} message={loadingMessage} />
            )}
            {tableState === 'EMPTY' && (
              <EmptyTable span={getColumnsQuantity()} message={emptyMessage} />
            )}
            {tableState === 'WITH_DATA' &&
              (pagination ? page : rows).map((row: any, index: number) => {
                const isRowExpandable = expandable?.rowHasExpandFeature(row.values as T);
                prepareRow(row);
                return (
                  <TableRow
                    key={row.getRowProps().key}
                    dataLength={data.length}
                    cellHeight={cellHeight}
                    expandableRender={expandable?.render}
                    isRowExpandable={isRowExpandable}
                    row={row}
                    {...(selectable?.useCheckbox === false
                      ? { onRowSelect: (rowData) => onTableRowSelect(rowData) }
                      : {})}
                    rowIndex={index}
                    onRow={onRow}
                  />
                );
              })}
          </Styled.Tbody>
        </Styled.Table>
      </Styled.TableContainer>
      {pagination !== false && (
        <TableFooter
          {...DEFAULT_PAGINATION}
          total={pagination.total || rows.length}
          pageSize={pageSize}
          current={pageIndex + 1}
          {...pagination}
          onChange={onPaginationChange}
        />
      )}
    </Styled.Container>
  );
};

export default React.forwardRef(Table) as typeof Table;
